import{_ as i,l as o,o as e,c as l,v as t,p as n,x as r,d as A,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"MAC 学习与洪泛","description":"","frontmatter":{"title":"MAC 学习与洪泛","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mac-learning.md","filePath":"cs/mac-learning.md","lastUpdated":1789023840000}'),c={name:"cs/mac-learning.md"};function h(m,a,_,E,u,C){const s=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="mac-学习与洪泛" tabindex="-1">MAC 学习与洪泛 <a class="header-anchor" href="#mac-学习与洪泛" aria-label="Permalink to &quot;MAC 学习与洪泛&quot;">​</a></h1><div class="epigraph"><p>源地址写入入端口的转发表，目的命中则单播，未知、广播、组播则洪泛；表会老化，环会让表振荡。</p><footer>—— 据 Kurose and Ross 交换章；IEEE 802.1Q 转发表条款整理</footer></div><p><a href="/cs/rstp-mstp">上一课</a>保证无环之后，洪泛才安全。主干<a href="/cs/csma-switch">CSMA 与交换</a> 已给过学习直觉。缺口是<strong>表项生命周期与洪泛集合</strong>：老化、VLAN 隔离、未知单播行为、与 LACP 逻辑口。本课不把交换芯片背板写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>帧进来：学源 MAC → 查目的。命中且出口≠入口则转发；同口则过滤（到自己）。未命中：向该 VLAN 内除入口外的转发态口洪泛。老化（常见 300 s）防止主机搬家后黑洞。RSTP 拓扑变更缩短老化，否则帧仍从旧口出。</p><p>组播若无 IGMP 窥探（后课）当广播洪泛。这是二层默认，不是 bug。</p><p><span class="marginnote">表容量有限：溢出则更多未知洪泛，像回到集线器。CAM 耗尽攻击是安全课对象，本课只钉机制。</span></p><h3 id="学源查宿" tabindex="-1">学源查宿 <a class="header-anchor" href="#学源查宿" aria-label="Permalink to &quot;学源查宿&quot;">​</a></h3><p>未知单播在 VLAN 内洪泛；表满则更像集线器。TCN 缩短老化，否则走旧口。ARP 表在主机，交换机只搬 MAC。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：学习、查找、洪泛、老化、TCN 冲刷。对照路由器：路由器不因源 IP 学出接口来转发（除某些特殊），交换机必须学。LACP：学在逻辑口上，哈希再选成员。</p>',11)),(e(),n(p,null,{default:r(()=>[d(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%85%A5%E5%B8%A7%22%5D%20--%3E%20LRN%5B%22%E5%AD%A6%E6%BA%90%20MAC%22%5D%0A%20%20LRN%20--%3E%20LK%5B%22%E6%9F%A5%E7%9B%AE%E7%9A%84%22%5D%0A%20%20LK%20--%3E%20HIT%5B%22%E5%8D%95%E7%AB%AF%E5%8F%A3%E5%87%BA%22%5D%0A%20%20LK%20--%3E%20FLOOD%5B%22VLAN%20%E5%86%85%E6%B4%AA%E6%B3%9B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>巨帧、PAUSE 不改学习键：键是 MAC+VLAN。LLDP 源 MAC 也会被学到，除非控制帧另通道。生成树阻塞口不学习数据，仍可收 BPDU。</p><p>未知单播洪泛会把流量送到所有接入口：大二层数据中心的痛点，后课 VXLAN/EVPN 用控制面分发 MAC 来收敛洪泛。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 EVPN 路由类型。交换机架构与背板是下一课。后课默认：学习+老化+洪泛是二层转发的全部控制面（无路由协议）。</p><p>不要把 MAC 表当成 ARP 表：ARP 在主机把 IP 映到 MAC；交换机只搬 MAC。</p><p>上一课留下的缺口在本课收口；「MAC 学习与洪泛」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/switch-fabric">交换机架构与背板</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>学源、查宿；未知则 VLAN 洪泛。</li><li>老化与 TCN 防止走旧口。</li><li>表满则洪泛增多。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Kurose and Ross；IEEE 802.1Q。</li></ul>',10))])}const N=i(c,[["render",h]]);export{f as __pageData,N as default};
